// Test order for the manual trigger. It deducts real stock ONCE:
// 24KGNORM -2, NEWBENCH -1, ADSNORM -1 (variant MIQ-ADPO-004).
// Running it again does nothing, because order TEST-001 is already recorded.
return [
  {
    json: {
      id: 'TEST-001',
      name: '#TEST-001',
      line_items: [
        { variant_id: 53211248099664, sku: 'MIQ-ADPO-004', quantity: 1, title: 'Test line' },
      ],
    },
  },
];

// Turns the Shopify order into one item for the database step.
// The line items travel as base64 text so commas and quotes cannot break the query parameter.
const order = $input.first().json;

const lines = (order.line_items || []).map(item => ({
  order_id: String(order.id),
  order_name: order.name,
  variant_id: String(item.variant_id),
  sku: item.sku,
  quantity_sold: Number(item.quantity),
}));

if (lines.length === 0) {
  return [];
}

return [
  {
    json: {
      order_id: String(order.id),
      order_name: order.name,
      line_count: lines.length,
      lines,
      payload_b64: Buffer.from(JSON.stringify(lines), 'utf8').toString('base64'),
    },
  },
];

const items = $input.all().map(i => i.json);

const lowStockItems = items.filter(item => item.is_low_stock === true);

if (lowStockItems.length === 0) {
  return [];
}

return [
  {
    json: {
      order_id: lowStockItems[0].order_id,
      order_name: lowStockItems[0].order_name,
      low_stock_items: lowStockItems,
      message: lowStockItems.map(item =>
        `${item.item_code} - ${item.item_name || ''}: current stock ${item.stock_after}, threshold ${item.stock_threshold}`
      ).join('\n'),
    },
  },
];
